\begin{corollary}[Essential incompleteness of arithmetic]
\label{cor:arithmetic}
\label{thm:arithmetic-comparison-inseparability}
For every consistent c.e.\ extension of PA, its theorem and
refutation sets of sentence codes are recursively inseparable.
Consequently every consistent c.e.\ extension of it is incomplete.
\end{corollary}

\begin{proposition}\label{prop:arithmetic-theory-realization}
Fix $d\ge0$, let $V=(1,\N)$, and let
$\Sigma_k=(1,\Sigma_{k,0})$ and $\Pi_k=(1,\Pi_{k,0})$
have recursive carriers for $0\le k\le d$. Then the
syntax and list algebras of Definition~\ref{def:categorical-syntax}
exist in $\mathcal C_{\mathrm{rec}}$ and are stable under parameters.
For every axiom subobject of the sentence object, the inference
endofunctor of Theorem~\ref{thm:first-order-theory} has an initial
algebra of finite derivations.
\end{proposition}

\subsection{Numerical incompleteness}
\label{sec:numerical-incompleteness}
\label{subsec:numerical-incompleteness}

\begin{lemma}[The theory generated by the diagonal pair]
\label{lem:arithmetic-signed-theory}
Assume that $\PA$ is consistent. The pair $a_0,a_1$ is inseparable
in $\mathscr C_{\PA}$, and the internal theory $t_{\pm}$ is
consistent and essentially incomplete.
\end{lemma}

\begin{proposition}\label{prop:miller-category}
The category $\mathcal E_a$ is a locally connected recursion category
with ranges, binary restriction coproducts, and finite compatible joins.
It satisfies weak choice, and $\tau_a:\N\times\N\rightharpoonup\N$
is a Turing morphism.
\end{proposition}

\begin{lemma}\label{lem:miller-cut-reduction}
There is a total recursive map $h:\N\to\N$ such that
\[
 h^{-1}(L_a)=A_0,\qquad h^{-1}(R_a)=A_1.
\]
\end{lemma}

\begin{corollary}\label{cor:miller-cuts-inseparable}
The restriction idempotents $1_{L_a},1_{R_a}:\N\rightharpoonup\N$ are inseparable in
$\mathcal E_a$. Every $p\in P_a$ computes a separator
of the underlying sets $L_a,R_a$.
\end{corollary}

\begin{proposition}\label{prop:fork-syntax-initial}
The algebra $\iota$ is initial: for every
$\alpha:P(Z)\to Z$ in $\mathcal E$, there is a unique morphism
$u:S\to Z$ in $\mathcal E$ satisfying $u\iota=\alpha P(u)$.
\end{proposition}

\begin{proposition}\label{prop:fork-proof-initial}
The algebra $\delta$ is initial. For every
$\eta:\mathsf H(Y,h)\to(Y,h)$ in $\mathcal E/S$, there is a
unique morphism $u:\mathrm{Prf}\to Y$ of $\mathcal E$ with
$hu=c_{\mathrm p}$ and $u\delta=\eta\mathsf H(u)$.
\end{proposition}

\begin{theorem}\label{thm:fork-proof-presentation}
The subfunctor $D_{t_0}\subseteq S$ is the least c.e. subfunctor
containing the logical and positive and negative atomic axioms and
closed under modus ponens. Its component theories are consistent,
and
\begin{equation}\label{eq:atomic-inequalities}
 1_A\le\theta^*t_0,\qquad
 1_B\le\theta^*\nu^*t_0,\qquad t_0\nu^*t_0=0_S.
\end{equation}
\end{theorem}

\begin{corollary}\label{cor:cosheaf-essential-incompleteness}
For each $i\in\{1,2\}$, the propositional theory with theorem set
$(D_{t_0})_i$ is essentially incomplete: every consistent extension in
the same language with a computably enumerable axiom set is incomplete.
\end{corollary}

\begin{proposition}\label{prop:fork-first-order-realization}
For every $D\in\mathcal E$, this language has the syntax,
substitution, and initial derivation algebras of
Appendix~\ref{app:syntax-theories}. The syntax and derivation
constructions are stable under parameters in $\mathcal E$.
\end{proposition}

\section{Syntax and deductively closed theories}
\label{app:syntax-theories}
\label{app:fork-proofs}

\begin{definition}\label{def:categorical-syntax}
A named-variable syntax object is an initial $K$-algebra
$\iota:K(\Tm,\Fm)\to(\Tm,\Fm)$ stable under parameters.
We also require a list object $W=\List V$, given by an initial
algebra $[\nil,\cons]:1+V\times W\to W$ stable under parameters.
\end{definition}

\begin{definition}\label{def:sentence-object}
The sentence object $j:S\hookrightarrow\Fm$ is the pullback
\[
\begin{tikzcd}
 S\arrow[r,hook,"j"]\arrow[d] & \Fm\arrow[d,"\FV_{\Fm}"]\\
 1\arrow[r,"\nil"'] & W.
\end{tikzcd}
\]
\end{definition}

\begin{theorem}\label{thm:least-theorem-subobject}
With the rule data above, suppose
$\delta:H(P,c)\to(P,c)$ is an initial algebra in $\mathcal D/F$.
The image of its conclusion morphism $c:P\to F$ is the least
subobject of $F$ closed under the rules.
\end{theorem}

\begin{theorem}\label{thm:first-order-theory}
Suppose $H_A$ has an initial algebra with conclusion morphism
$c_A:P_A\to F$. Its image $T_A\hookrightarrow F$ is the least
subobject containing the logical and nonlogical axioms and closed
under generalization and modus ponens. The image of the pullback
\[
\begin{tikzcd}
 P_{A,S}\arrow[r]\arrow[d,"c_{A,S}"'] & P_A\arrow[d,"c_A"]\\
 S\arrow[r,hook,"j"'] & F
\end{tikzcd}
\]
is $T_{A,S}=S\times_F T_A\hookrightarrow S$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:least-theorem-subobject} gives the first assertion.
Regular images are stable under pullback, giving the second.
\end{proof}

\begin{proposition}\label{prop:fork-local}
The category $\mathcal A$ is locally connected.
\end{proposition}

\begin{lemma}\label{lem:fork-dominance}
Every object $Y$ of $\mathcal E$ admits a restriction monomorphism
$s_Y:Y\to V$ in $\mathcal A$.
\end{lemma}

\begin{lemma}\label{lem:fork-frames}
There are isomorphisms in $\mathcal E$
$V\cong V\times V$, $V\cong V+V$, and $V\cong V^\#$.
\end{lemma}

\begin{corollary}\label{cor:fork-karoubi}
Every idempotent in $\mathcal A$ splits, and the inclusion
$\mathscr R_X\hookrightarrow\mathcal A$ extends, up to natural
isomorphism, to a restriction equivalence
$Q:\operatorname{Kar}(\mathscr R_X)\to\mathcal A$.
\end{corollary}

\begin{proposition}\label{prop:fork-distinction}
The recursion category $\mathscr R_X$ is not equivalent, as a
restriction category, to the recursion category of partial recursive functions.
The object $V$ has no decidable equality in $\mathcal E$.
\end{proposition}

